import numpy as np

def transform(grid):
    grid = np.array(grid)
    rows, cols = grid.shape
    output = grid.copy()

    coords = np.argwhere(grid == 2)
    rows_with_2 = set()
    cols_with_2 = set()
    for r, c in coords:
        rows_with_2.add(r)
        cols_with_2.add(c)

    for r in rows_with_2:
        for j in range(cols):
            if output[r, j] == 0:
                output[r, j] = 2

    for c in cols_with_2:
        for i in range(rows):
            if output[i, c] == 0:
                output[i, c] = 2

    return output.tolist()

