import numpy as np

def transform(grid):
    grid = np.array(grid)
    rows, cols = grid.shape
    output = grid.copy()

    anchor_color = -1
    for r in range(rows):
        for c in range(cols):
            val = grid[r, c]
            if val != 0 and val != 1:
                anchor_color = val
                break
        if anchor_color != -1:
            break

    if anchor_color == -1:
        return grid.tolist()

    # The logic: For every anchor point, fill the 3x3 neighborhood with 1s.
    # If a cell is already an anchor point, it stays as the anchor point.
    # If a cell is already a 1, it stays 1.
    # If a cell is 0, it becomes 1.

    # We must iterate through the original grid to find anchors
    anchors = []
    for r in range(rows):
        for c in range(cols):
            if grid[r, c] == anchor_color:
                anchors.append((r, c))

    for r, c in anchors:
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if output[nr, nc] == 0:
                        output[nr, nc] = 1

    return output.tolist()

