import numpy as np

def transform(grid):
    grid = np.array(grid)
    output = grid.copy()
    rows, cols = grid.shape

    for r in range(rows):
        source_color = None
        # Find the leftmost color that is NOT 0 and NOT 5
        for c in range(cols):
            if grid[r, c] != 0 and grid[r, c] != 5:
                source_color = grid[r, c]
                break

        if source_color is not None:
            for c in range(cols):
                if grid[r, c] == 5:
                    output[r, c] = source_color

    return output
